// Group 16 fixture. Loopback-only server consumes this; never imported by product.
export function managementFixture({owner,fid,date,scenario='normal'}){
 const calls=[],read=new Set(),receipts=new Map(),jobs=new Map();let pendingReads=0,authenticated=false,unknownImport=false;const adopted={};
 const config={effective_values:{},endpoints:scenario==='empty'?[]:[{id:'fixture-model',kind:'openai-compatible',base_url:'http://fixture-model.invalid/v1',secret_configured:false}],bindings:scenario==='empty'?[]:[{role:'generic_llm',endpoint_id:'fixture-model',model_id:'fixture-model',timeout_seconds:120}],versions:{'endpoint:fixture-model':1,'binding:generic_llm':1}};
 const notices=[{id:'inbox-fixture-one',fluctlight_id:fid,title:'日常准备需要继续',body:'图片准备暂时中断，可以查看原任务与真实恢复方式。',link:'/diag/task/task-fixture',created_at:date},{id:'inbox-fixture-two',fluctlight_id:fid,title:'新的生活近况',body:'这是一条来自隔离验收环境的通知，标为已读不会处理其他事项。',link:'/c/'+fid+'/chat',created_at:date}];
 return {calls,async handler({path,method,body,url,json,res}){
  if(path==='/fixture/management-scenario'){scenario=url.searchParams.get('value')||'normal';if(scenario.startsWith('auth'))authenticated=false;json(res,{scenario,calls});return true;}
  if(scenario.startsWith('auth')&&path==='/auth/session'){json(res,authenticated?{authenticated:true,actorId:owner}:{authenticated:false});return true;}
  if(scenario.startsWith('auth')&&path==='/auth/setup-status'){if(scenario==='auth-loading')await new Promise(r=>setTimeout(r,2000));if(scenario==='auth-read-failure'){json(res,{message:'隔离账户状态读取失败'},503);return true;}json(res,{setupAvailable:scenario==='auth-setup'});return true;}
  if(scenario.startsWith('auth')&&['/auth/login','/auth/setup'].includes(path)){calls.push({path,method,credential_fields:Object.keys(body)});if(scenario==='auth-failure'){json(res,{error:'隔离样本：密码未被接受'},401);return true;}if(scenario==='auth-loading')await new Promise(r=>setTimeout(r,1800));authenticated=true;json(res,{authenticated:true,actorId:owner});return true;}
  if(path==='/auth/logout'&&method==='POST'){authenticated=false;scenario='auth-login';json(res,{});return true;}
  if(path.startsWith('/api/ops/backups')){if(scenario==='loading')await new Promise(r=>setTimeout(r,1800));if(scenario==='failure'){json(res,{message:'隔离备份来源读取失败'},503);return true;}const parts=path.split('/'),id=parts[4];if(method==='POST'){let job=id?jobs.get(id):null;const action=parts[5]||'create';if(!job)job={id:'backup-created-'+jobs.size,kind:'backup',status:'queued',revision:1,attempt:1,reason:body.reason,stage:'queued',result:{},steps:[],created_at:date};if(action==='restore')job={...job,id:'restore-created-'+jobs.size,kind:'restore',source_backup_id:id,status:'queued',target_name:body.targetName,revision:1,stage:'queued',result:{},steps:[],started_at:null,finished_at:null};if(action==='cancel')job={...job,status:'cancelled',revision:job.revision+1};if(action==='retry')job={...job,status:'queued',attempt:job.attempt+1,revision:job.revision+1};jobs.set(job.id,job);calls.push({path,method,body});json(res,job);return true;}if(!jobs.size&&scenario!=='empty'){for(const [i,status] of ['completed','failed','queued'].entries())jobs.set('backup-'+status,{id:'backup-'+status,kind:'backup',source_backup_id:null,target_name:null,status,revision:2,attempt:i+1,reason:'隔离维护样本',stage:status==='completed'?'backup_verified':'queued',result:status==='completed'?{restorable:true}: {},steps:[],created_at:date,started_at:status==='queued'?null:date,finished_at:status==='completed'?date:null});}json(res,id?jobs.get(id):{items:scenario==='empty'?[]:[...jobs.values()],next_cursor:'',maintenance_required:true});return true;}
  if(path.startsWith('/api/studio/packs')){const pack={schema:'fluctlight.resource-pack.v1',created_at:date,checksum:'fixture-checksum',resources:[{key:'resource-fixture',kind:'item',name:'窗边书签',body:{name:'窗边书签',description:'保留的样本定义'}}],groups:[{name:'导入建议分组'}],preferences:{}};const validation={valid:true,schema:pack.schema,digest:'fixture-exact-digest',entries:[{entry_key:'resource-fixture',kind:'item',name:'窗边书签'}],publish_order:['resource-fixture'],external_bindings:[],semantics:'仅创建独立定义草稿，不发布、不应用、不覆盖生活数据。'};if(scenario==='failure'){json(res,{message:'隔离资源包校验失败'},503);return true;}if(scenario==='loading')await new Promise(r=>setTimeout(r,1500));if(path.endsWith('/export')){json(res,{pack,validation,complete:true,available:true,scope:'saved-definition'});return true;}if(path.endsWith('/validate')){json(res,validation);return true;}if(path==='/api/studio/packs'&&method==='POST'){calls.push({path,method,body});if(scenario==='unknown-import'&&!unknownImport){unknownImport=true;json(res,{message:'隔离样本：原导入结果暂未确认'},503);return true;}json(res,{pack_id:'pack-fixture',status:'imported',resource_versions:[{resource_id:'resource-fixture',version:'draft:1'}],digest:validation.digest,life_write:false,published:false});return true;}if(path.includes('/groups/')){calls.push({path,method,body});adopted[path.split('/')[6]]={id:'group-imported',name:body.name};json(res,adopted[path.split('/')[6]]);return true;}json(res,{id:'pack-fixture',revision:1,digest:validation.digest,created_at:date,resource_versions:[{entry_key:'resource-fixture',resource_id:'resource-fixture',version:'draft:1',kind:'item',name:'窗边书签'}],groups:pack.groups,adopted_groups:adopted,preferences:{},publish_order:validation.publish_order,external_bindings:[]});return true;}
  if(path==='/api/data/revisions'){json(res,{items:[],next_cursor:''});return true;}
  if(path.startsWith('/api/diagnostics/tasks/')){if(scenario==='loading')await new Promise(r=>setTimeout(r,1800));if(scenario==='failure'){json(res,{message:'隔离任务详情读取失败'},503);return true;}json(res,{task_id:'task-fixture',workflow_id:'workflow-fixture',fluctlight_id:fid,kind:'visual_identity.prepare',status:'failed',runs:2,created_at:date,started_at:date,completed_at:date,source:{last_error:'隔离样本：服务连接暂不可用'},steps:scenario==='empty'?[]:[{id:'s1',name:'确认角色资料',status:'completed',at:date},{id:'s2',name:'准备图片',status:'failed',reason_code:'provider_unavailable',at:date}],has_more_steps:false});return true;}
  if(path.startsWith('/api/workflow-controls/')){if(method==='GET'){json(res,path.endsWith('/history')?{items:[{id:4,type:'ActivityTaskCompleted',at:date,resettable:true,details:{result:'已确认资料'}}],next_cursor:''}:{intent:{id:'task-fixture',status:'failed',revision:3},runtime:{run_id:'run-fixture',status:'failed'},runtime_state:'available',allowed_actions:scenario==='empty'?[]:['restart','reset'],commands:[],control_semantics:'沿用原任务输入。提交后读取实际执行状态。'});return true;}calls.push({path,method,body});json(res,{status:'accepted'});return true;}
  if(path.startsWith('/api/diagnostic-records/')){if(scenario==='loading')await new Promise(r=>setTimeout(r,1500));if(scenario==='failure'){json(res,{message:'隔离调用列表读取失败'},503);return true;}const kind=decodeURIComponent(path.split('/')[3]);const row={kind,ref:kind+'-fixture',occurred_at:date,data:{id:'task-fixture',intent_type:'visual_identity.prepare',fluctlight_id:fid,status:'failed',created_at:date,started_at:date,completed_at:date,model_id:'fixture-model',binding_role:'generic_llm',scenario:'wake_up',error_code:'provider_request_failed',prompt:[{role:'user',content:'隔离样本输入'}],response:null}};json(res,path.split('/').length>4?row:{items:scenario==='empty'||!['workflow-intents','model-runs'].includes(kind)?[]:[row],next_cursor:''});return true;}
  if(path==='/api/configuration-catalog'){if(scenario==='loading')await new Promise(r=>setTimeout(r,2000));if(scenario==='failure'){json(res,{message:'隔离配置读取失败'},503);return true;}json(res,config);return true;}
  if(path.startsWith('/api/configuration-commands/')){json(res,receipts.get(url.searchParams.get('key')||body.key)||{status:'applied',applied_versions:config.versions});return true;}
  if((path==='/api/providers/endpoints'||path==='/api/providers/roles'||path==='/api/settings')&&method!=='GET'){const key=body.idempotencyKey;calls.push({path,method,body});if(path.endsWith('/endpoints')){config.endpoints=config.endpoints.filter(e=>e.id!==body.endpointId).concat({id:body.endpointId,kind:body.kind,base_url:body.baseUrl,secret_configured:false});config.bindings=config.bindings.filter(b=>b.endpoint_id!==body.endpointId);}else if(path.endsWith('/roles'))config.bindings=config.bindings.filter(b=>b.role!==body.role).concat({role:body.role,endpoint_id:body.endpointId,model_id:body.modelId,timeout_seconds:body.timeoutSeconds});else Object.assign(config.effective_values,body.values||{});const receipt={status:'applied',applied_versions:config.versions};receipts.set(key,receipt);json(res,receipt);return true;}
  if(!path.startsWith('/api/notifications')&&!path.startsWith('/api/pending'))return false;
  calls.push({path,method,body,query:Object.fromEntries(url.searchParams)});
  if(scenario==='loading')await new Promise(resolve=>setTimeout(resolve,2200));
  if(scenario==='failure'&&method==='GET'){json(res,{message:'隔离样本：通知来源读取失败'},503);return true;}
  if(path==='/api/notifications/unread-count'){json(res,{count:notices.filter(n=>!read.has(n.id)).length});return true;}
  if(path==='/api/notifications'&&method==='GET'){json(res,{items:scenario==='empty'?[]:notices.map(n=>({...n,read_at:read.has(n.id)?date:null})),as_of:date,next_cursor:''});return true;}
  if(method==='POST'&&path.includes('/read')){if(path.includes('read-all'))notices.forEach(n=>read.add(n.id));else read.add(decodeURIComponent(path.split('/')[3]));json(res,{});return true;}
  if(path==='/api/pending/count'){json(res,{count:scenario==='empty'?0:2});return true;}
  if(path==='/api/pending'){pendingReads++;json(res,{groups:['capability','persona_proposal','studio_apply','failed_task','owner_request'].filter(kind=>!url.searchParams.get('kind')||url.searchParams.get('kind')===kind).map(kind=>({kind,status:'ok',count:scenario==='empty'?0:kind==='persona_proposal'||kind==='failed_task'?1:0,items:scenario==='empty'?[]:kind==='persona_proposal'?[{id:'proposal-inbox',title:'审阅角色身份提议',fluctlight_id:fid,status:'pending',href:'/diag/pending',created_at:date}]:kind==='failed_task'?[{id:'task-fixture',title:'查看原任务与恢复方式',fluctlight_id:fid,status:'failed',href:'/diag/task/task-fixture',created_at:date}]:[],next_cursor:''}))});return true;}
  return false;
 }};
}
